import{_ as t,o,c as a,a0 as r}from"./chunks/framework.BywSET8q.js";const u=JSON.parse('{"title":"Class: AuthorizationCodeFlow","description":"","frontmatter":{},"headers":[],"relativePath":"api/spa-platform/flows/AuthorizationCodeFlow/index.md","filePath":"api/spa-platform/flows/AuthorizationCodeFlow/index.md"}'),i={name:"api/spa-platform/flows/AuthorizationCodeFlow/index.md"};function d(l,e,s,n,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<p><a href="./../..">@okta/spa-platform</a> / <a href="./../">Flows</a> / AuthorizationCodeFlow</p><h1 id="class-authorizationcodeflow" tabindex="-1">Class: AuthorizationCodeFlow <a class="header-anchor" href="#class-authorizationcodeflow" aria-label="Permalink to &quot;Class: AuthorizationCodeFlow&quot;">​</a></h1><p>Browser-specific additions to <a href="https:/okta.github.io/okta-client-javascript/api/oauth2-flows/AuthorizationCodeFlow/">AuthorizationCodeFlow</a></p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to &quot;Extends&quot;">​</a></h2><ul><li><a href="https:/okta.github.io/okta-client-javascript/api/oauth2-flows/AuthorizationCodeFlow/"><code>AuthorizationCodeFlow</code></a></li></ul><h2 id="authorize-methods" tabindex="-1">Authorize Methods <a class="header-anchor" href="#authorize-methods" aria-label="Permalink to &quot;Authorize Methods&quot;">​</a></h2><h3 id="performredirect" tabindex="-1">PerformRedirect() <a class="header-anchor" href="#performredirect" aria-label="Permalink to &quot;PerformRedirect()&quot;">​</a></h3><blockquote><p><code>static</code> <strong>PerformRedirect</strong>(<code>flow</code>): <a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise" target="_blank" rel="noreferrer"><code>Promise</code></a>&lt;<code>void</code>&gt;</p></blockquote><p>Performs a browser full-page redirect to the <code>Authorization Server</code> <code>/authorize</code> endpoint. Once authentication is successful, the user will be redirected back to the provided <code>redirectUri</code></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>AuthorizationCodeFlow</code></td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise" target="_blank" rel="noreferrer"><code>Promise</code></a>&lt;<code>void</code>&gt;</p><h4 id="remarks" tabindex="-1">Remarks <a class="header-anchor" href="#remarks" aria-label="Permalink to &quot;Remarks&quot;">​</a></h4><p>This method returns a <code>Promise</code> that will never fulfill; a browser redirect will occur first</p><h4 id="see" tabindex="-1">See <a class="header-anchor" href="#see" aria-label="Permalink to &quot;See&quot;">​</a></h4><ul><li><a href="https:/okta.github.io/okta-client-javascript/api/oauth2-flows">AuthorizationCodeFlow.resume</a></li><li><a href="https:/okta.github.io/okta-client-javascript/api/spa-platform/#performredirect">SPA Platform: PerformRedirect</a></li></ul><hr><h3 id="performsilently" tabindex="-1">PerformSilently() <a class="header-anchor" href="#performsilently" aria-label="Permalink to &quot;PerformSilently()&quot;">​</a></h3><blockquote><p><code>static</code> <strong>PerformSilently</strong>(<code>flow</code>): <a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise" target="_blank" rel="noreferrer"><code>Promise</code></a>&lt;<a href="./type-aliases/Result"><code>Result</code></a>&gt;</p></blockquote><p>Fulfills the <code>/authorize</code> request within a hidden iframe and therefore does <em>not</em> require a redirect. This requires an existing cookie-based session with the IDP and is susceptible to third-party cookie restrictions.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>AuthorizationCodeFlow</code></td></tr></tbody></table><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise" target="_blank" rel="noreferrer"><code>Promise</code></a>&lt;<a href="./type-aliases/Result"><code>Result</code></a>&gt;</p><p>Returns a <a href="https:/okta.github.io/okta-client-javascript/api/auth-foundation/Token/">Token</a> and the <a href="./interfaces/Context">AuthorizationCodeFlow.Context</a> used to request the token</p><h4 id="remarks-1" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-1" aria-label="Permalink to &quot;Remarks&quot;">​</a></h4><p>This approach is not recommended for most common use cases and may be deprecated in the future. Use <a href="#performredirect">AuthorizationCodeFlow.PerformRedirect</a> instead</p><h4 id="see-1" tabindex="-1">See <a class="header-anchor" href="#see-1" aria-label="Permalink to &quot;See&quot;">​</a></h4><ul><li><a href="https://auth0.com/docs/authenticate/login/configure-silent-authentication" target="_blank" rel="noreferrer">Silent Authentication</a></li><li><a href="https://developers.google.com/privacy-sandbox/cookies" target="_blank" rel="noreferrer">Third-party Cookie Deprecation</a></li><li><a href="https:/okta.github.io/okta-client-javascript/api/spa-platform/#performsilently">SPA Platform: PerformSilently</a></li></ul><hr><h3 id="performinpopup" tabindex="-1">PerformInPopup() <a class="header-anchor" href="#performinpopup" aria-label="Permalink to &quot;PerformInPopup()&quot;">​</a></h3><blockquote><p><code>static</code> <strong>PerformInPopup</strong>(<code>flow</code>, <code>popupWindow?</code>): <a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise" target="_blank" rel="noreferrer"><code>Promise</code></a>&lt;<a href="./type-aliases/PopupResult"><code>PopupResult</code></a>&gt;</p></blockquote><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Read carefully before use. This method (and popup pattern at large) has quite a few &quot;gotchas&quot;</p></div><p>Fulfills <code>/authorize</code> requests in a popup window. Not necessarily recommended for primary authentication flows, but can be useful for step up authentication flows against a known IDP.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The phrase &quot;external IDP&quot; refers to an IDP other than the configured <code>issuer</code> for a given flow. See <a href="https://developer.okta.com/docs/concepts/identity-providers/" target="_blank" rel="noreferrer">Concepts: External Identity Providers</a> for a more detailed explanation</p></div><p>Utilizing external IDPs in a popup window may be susceptible to the IDP&#39;s <code>Cross-Origin-Opener-Policy</code>. Depending on their policy value, loading the IDP in a popup window may cause the popup window to create a new browsing context group (BCG), seperate from the main browser window. The authentication flow will be unable to complete if this occurs. It&#39;s recommended to avoid using this method (and a popup in general) when utilizing external IDPs.</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cross-Origin-Opener-Policy" target="_blank" rel="noreferrer">Cross-Origin-Opener-Policy</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Glossary/Browsing_context" target="_blank" rel="noreferrer">Browsing Context Group</a></li></ul><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>AuthorizationCodeFlow</code></td><td>instance of AuthorizationCodeFlow to be used</td></tr><tr><td><code>popupWindow?</code></td><td><a href="https://developer.mozilla.org/docs/Web/API/Window" target="_blank" rel="noreferrer"><code>Window</code></a></td><td>Optionally, a <code>Window</code> object (representing a popup window) can be provided. Providing a popup reference can be useful when control over the popup&#39;s attributes, like name and size, is required. In addition, the popup window will first load the base route (<code>/</code>) of the web application. Some browser implement heustistics which can block popups spawned from <code>async</code> processes. Loading the base route before navigating to <code>/authorize</code> helps reduce the likelihood the popup gets blocked. To override this behavior, provide a popup reference</td></tr></tbody></table><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise" target="_blank" rel="noreferrer"><code>Promise</code></a>&lt;<a href="./type-aliases/PopupResult"><code>PopupResult</code></a>&gt;</p><p>Success response:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>completed</code></td><td><code>true</code></td><td>Indicates the flow completed successfully</td></tr><tr><td><code>token</code></td><td><a href="https:/okta.github.io/okta-client-javascript/api/auth-foundation/Token/">Token</a></td><td>The resulting token from the successful flow</td></tr><tr><td><code>context</code></td><td><code>Record&lt;string, any&gt;</code></td><td>Developer-provided (pre-auth) metadata about the token</td></tr></tbody></table><p>Unsuccessful response:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>completed</code></td><td><code>false</code></td><td>Indicates the flow <strong>did not</strong> complete</td></tr><tr><td><code>reason</code></td><td><code>&#39;closed&#39;</code> or <code>&#39;blocked&#39;</code></td><td>Indicates the <em>reason</em> the flow did not complete</td></tr></tbody></table><ul><li><code>&#39;closed&#39;</code> indicates the user manually closed the popup window</li><li><code>&#39;blocked&#39;</code> indicates the popup window was unable to be opened (presumably by a popup blocker or browser heustistics)</li></ul><h4 id="see-2" tabindex="-1">See <a class="header-anchor" href="#see-2" aria-label="Permalink to &quot;See&quot;">​</a></h4><ul><li><a href="https:/okta.github.io/okta-client-javascript/api/spa-platform/#performinpopup">SPA Platform: PerformInPopup</a></li></ul><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/RedirectValues">RedirectValues</a></td><td>Values parsed from a successful redirect back from the Authorization Server</td></tr><tr><td><a href="./interfaces/Context">Context</a></td><td>Values needed to initiate an Authorization Code flow</td></tr></tbody></table><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to &quot;Type Aliases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type Alias</th><th>Description</th></tr></thead><tbody><tr><td><a href="./type-aliases/Result">Result</a></td><td>The result of successfully completing an Authorization Code flow via <a href="https:/okta.github.io/okta-client-javascript/api/oauth2-flows">AuthorizationCodeFlow.resume</a></td></tr><tr><td><a href="./type-aliases/PopupResult">PopupResult</a></td><td>The possible results from <a href="./#performinpopup">AuthorizationCodeFlow.PerformInPopup</a></td></tr></tbody></table>',53)])])}const f=t(i,[["render",d]]);export{u as __pageData,f as default};
